package vn.xuannhashop.business.delivery.application;
import java.util.*;import java.time.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;import vn.xuannhashop.business.shared.security.ActorContext;import vn.xuannhashop.business.shared.audit.ActivityService;
import vn.xuannhashop.business.rental.application.RentalApplication;
@Service public class DeliveryPlanningService implements DeliveryPlanningApplication {
    private final DeliveryPlanningRepository r;private final RentalApplication rentals;private final ActorContext actor;private final Commands commands;private final ActivityService audit;
    public DeliveryPlanningService(DeliveryPlanningRepository r,RentalApplication rentals,ActorContext actor,Commands commands,ActivityService audit){this.r=r;this.rentals=rentals;this.actor=actor;this.commands=commands;this.audit=audit;}
    public Map<String,Object> overview(){actor.require("OWNER","MANAGER","INVENTORY","DELIVERY","TECHNICIAN");return r.overview(actor.current().role().equals("DELIVERY")?actor.username():null);}
    public Map<String,Object> guide(UUID id){var g=r.guide(id);return g==null?Map.of("version",0,"type_id",id):g;}
    @Transactional public UUID publish(Guide c,String key){actor.require("OWNER","TECHNICIAN");if(c==null||c.typeId()==null||c.expectedVersion()==null||c.expectedVersion()<0)throw DomainException.bad("Cần loại và phiên bản hướng dẫn.");Checks.text(c.title(),180,"Tên hướng dẫn");Checks.text(c.instructions(),12000,"Hướng dẫn sử dụng");Checks.text(c.safety(),6000,"Lưu ý an toàn");Checks.text(c.source(),500,"Nguồn hướng dẫn đã đối chiếu");return commands.once(key,"GUIDE_PUBLISH:"+c,()->{r.lockGuide(c.typeId());var current=r.guide(c.typeId());if((current==null?0:((Number)current.get("version")).longValue())!=c.expectedVersion())throw DomainException.conflict("Hướng dẫn đã đổi, tải lại phiên bản mới.");UUID id=UUID.randomUUID();r.publish(id,c,actor.username());audit.record("GUIDE_PUBLISHED",c.typeId(),c.source());return id;});}
    public Map<String,Object> orderGuides(UUID order){rentals.assertAccess(order);return Map.of("guides",r.orderGuides(order),"acknowledgements",r.acknowledgements(order));}
    @Transactional public UUID acknowledge(UUID order,UUID guide,String confirmed,String evidence,String key){rentals.assertAccess(order);actor.require("OWNER","MANAGER","INVENTORY","DELIVERY","CUSTOMER");if(guide==null)throw DomainException.bad("Chọn phiên bản hướng dẫn.");Checks.text(evidence,1000,"Căn cứ hướng dẫn");String name=actor.current().role().equals("CUSTOMER")?actor.current().displayName():Checks.text(confirmed,120,"Người đã được hướng dẫn");return commands.once(key,"GUIDE_ACK:"+order+":"+guide+":"+name+":"+evidence,()->{var o=r.order(order);if(o==null)throw DomainException.missing();if(Set.of("CANCELLED","EXPIRED","COMPLETED").contains(o.get("status")))throw DomainException.conflict("Đơn đã kết thúc.");var guides=r.orderGuides(order);var g=guides.stream().filter(v->guide.equals(v.get("id"))).findFirst().orElseThrow(()->DomainException.conflict("Hướng dẫn không thuộc phiên bản hiện hành của đơn."));r.lockGuide((UUID)g.get("type_id"));if(!r.guide((UUID)g.get("type_id")).get("id").equals(guide))throw DomainException.conflict("Hướng dẫn đã đổi, đọc lại trước khi xác nhận.");UUID id=UUID.randomUUID();r.acknowledge(id,order,guide,name,evidence,actor.current().role().equals("CUSTOMER")?"CUSTOMER":"STAFF_RECORDED",actor.username());audit.record("GUIDE_ACKNOWLEDGED",order,"guide="+guide);return id;});}
    @Transactional public void requireAcknowledged(UUID order,List<UUID> items){if(items==null||items.isEmpty())throw DomainException.bad("Chọn thiết bị bàn giao.");if(r.order(order)==null)throw DomainException.missing();for(var g:r.orderGuides(order).stream().sorted(Comparator.comparing(v->v.get("type_id").toString())).toList())r.lockGuide((UUID)g.get("type_id"));if(r.missingAcknowledgement(order,items))throw DomainException.conflict("Cần hướng dẫn và xác nhận phiên bản hiện hành trước khi giao thiết bị.");}
    @Transactional public UUID assign(Assignment c,String key){actor.require("OWNER","MANAGER","INVENTORY");if(c==null||c.orderId()==null||c.kind()==null||!Set.of("OUT","IN").contains(c.kind())||c.orderVersion()==null||c.startsAt()==null||c.endsAt()==null||!c.endsAt().isAfter(c.startsAt())||Duration.between(c.startsAt(),c.endsAt()).compareTo(Duration.ofHours(24))>0||!c.endsAt().isAfter(Instant.now()))throw DomainException.bad("Chọn đơn, loại công việc, phiên bản và khung giờ tối đa 24 giờ còn hiệu lực.");Checks.text(c.assignee(),80,"Nhân viên giao nhận");Checks.text(c.routeNote(),1000,"Lộ trình và yêu cầu giao nhận");return commands.once(key,"DISPATCH:"+c,()->{var o=r.order(c.orderId());if(o==null)throw DomainException.missing();if(!o.get("version").equals(c.orderVersion()))throw DomainException.conflict("Đơn đã đổi, kiểm tra lại lịch và địa chỉ.");if(!Set.of("CONFIRMED","PREPARING","RENTED","PARTIAL_RETURN").contains(o.get("status")))throw DomainException.conflict("Đơn chưa đủ điều kiện phân công.");if(!r.assignee(c.assignee()))throw DomainException.bad("Nhân viên giao nhận không hoạt động.");if(r.overlap(c))throw DomainException.conflict("Nhân viên đã có việc trong khung giờ này.");UUID id=UUID.randomUUID();r.assign(id,c,(String)o.get("address"),actor.username());audit.record("DELIVERY_ASSIGNED",c.orderId(),c.kind()+"; "+c.assignee());return id;});}
    @Transactional public void finish(UUID id,boolean completed,String outcome,String key){actor.require("OWNER","MANAGER","INVENTORY","DELIVERY");Checks.text(outcome,1000,"Kết quả/lý do hủy");commands.once(key,"DISPATCH_FINISH:"+id+":"+completed+":"+outcome,()->{var c=r.assignment(id);if(c==null)throw DomainException.missing();if(actor.current().role().equals("DELIVERY")&&!c.get("assignee").equals(actor.username()))throw DomainException.forbidden();if(!c.get("status").equals("ASSIGNED"))throw DomainException.conflict("Công việc đã kết thúc.");if(completed&&!r.performed((UUID)c.get("order_id"),(String)c.get("kind")))throw DomainException.conflict("Chưa có đủ biên bản giao/thu thực tế cho đơn; ghi nhận trước khi hoàn thành.");r.finish(id,completed,outcome);audit.record("DELIVERY_ASSIGNMENT_FINISHED",(UUID)c.get("order_id"),completed+"; "+outcome);return id;});}
}
